# dcgo_arena.py — DCGO 아레나 참가 SDK 단일 파일 (서버 자동 생성 — 편집 금지)
# 사용:  import dcgo_arena as da  /  python dcgo_arena.py daemon --config dcgo-arena.toml
import sys, types
_pkg = types.ModuleType('dcgo_arena'); _pkg.__path__ = []; sys.modules['dcgo_arena'] = _pkg
_SOURCES = {'__init__': '"""dcgo-arena — DigimonCardgame AI 아레나 참가 SDK (설계 v1 §1, M5 + TextArena식 고수준 API).\n\n빠른 시작 (TextArena 관례):\n    import dcgo_arena as da\n\n    da.play(\n        server="http://서버:8791", key="API키",\n        agent=da.agents.OpenAICompat(base_url="http://localhost:11434/v1", model="llama3"),\n        games=10,            # daemon=True 로 상주 참가\n    )\n\n덱은 SDK가 관여하지 않는다 — 생성·수정·사용 덱 지정은 전부 웹 참가자 페이지에서 하며,\n서버가 그 계정의 활성 덱을 자동 적용한다(사용자 확정 2026-07-31). agent 생략 = 무작위\n합법 수. 저수준(ArenaClient)·CLI(`python -m dcgo_arena play|daemon`)도 제공.\n"""\n\nfrom dcgo_arena import agents\nfrom dcgo_arena.client import ArenaClient, ArenaError\nfrom dcgo_arena.highlevel import daemon, play\nfrom dcgo_arena.policies import LLMPolicy, RandomPolicy\nfrom dcgo_arena.state_text import state_to_text\n\n__all__ = ["play", "daemon", "agents",\n           "ArenaClient", "ArenaError", "RandomPolicy", "LLMPolicy", "state_to_text"]\n',
  'state_text': '"""your_turn 페이로드 → LLM용 텍스트 상태 서술 (설계 §3.2: legalActions 서술형이 1차 요건).\n\nnames 사전(카드번호→한글명)을 주면 카드가 "가브몬(BT1-029)"처럼 병기된다\n(사용자 확정 2026-08-01: 기본 한글 — 스킬/LLM 경로의 카드 이해도 직결)."""\n\nfrom __future__ import annotations\n\nimport re\n\n_CARD_ID = re.compile(r"\\b([A-Z]+\\d*[-_]\\d+\\w*)\\b")\n\n\ndef _card(card_id: str, names: dict | None) -> str:\n    if names and card_id in names:\n        return f"{names[card_id]}({card_id})"\n    return card_id\n\n\ndef _perm(p: dict, names: dict | None) -> str:\n    bits = [_card(p["top"], names) if p.get("top") else "?"]\n    if p.get("level"):\n        bits.append(f"Lv{p[\'level\']}")\n    if p.get("dp"):\n        bits.append(f"DP{p[\'dp\']}")\n    if p.get("suspended"):\n        bits.append("레스트")\n    if p.get("roots"):\n        bits.append(f"진화원{len(p[\'roots\'])}")\n    return "(" + " ".join(str(b) for b in bits) + ")"\n\n\ndef _side(name: str, s: dict, mine: bool, names: dict | None) -> list[str]:\n    lines = [f"[{name}]"]\n    lines.append(f"  덱 {s.get(\'deckCount\', \'?\')}장 · 시큐리티 {s.get(\'securityCount\', \'?\')}장 · 트래시 {len(s.get(\'trash\', []))}장")\n    if mine and "hand" in s:\n        lines.append(f"  손패({len(s[\'hand\'])}): {\', \'.join(_card(c, names) for c in s[\'hand\']) or \'없음\'}")\n    elif "handCount" in s:\n        lines.append(f"  손패 {s[\'handCount\']}장(비공개)")\n    field = s.get("field") or []\n    lines.append(f"  배틀에어리어({len(field)}): {\' \'.join(_perm(p, names) for p in field) or \'없음\'}")\n    breeding = s.get("breeding") or []\n    if breeding:\n        lines.append(f"  육성: {\' \'.join(_perm(p, names) for p in breeding)}")\n    return lines\n\n\ndef state_to_text(turn: dict, names: dict | None = None) -> str:\n    """관측 필터된 state + 결정 종류 + 합법 수 목록을 사람이/LLM이 읽는 한 덩어리로."""\n    state = turn.get("state") or {}\n    seat = turn.get("seat")\n    me, foe = ("p1", "p2") if seat == 1 else ("p2", "p1")\n    memory = state.get("memory", 0)\n    my_memory = -memory if me == "p1" else memory   # 음수 = P1 보유(뷰어 관례)\n\n    lines = [f"턴 {state.get(\'turn\')} · {state.get(\'phase\')} · 내 좌석 P{seat}",\n             f"메모리: 내 쪽 {my_memory:+d}" if isinstance(memory, int) else "메모리: ?"]\n    lines += _side("나", state.get(me) or {}, mine=True, names=names)\n    lines += _side("상대", state.get(foe) or {}, mine=False, names=names)\n    lines.append(f"결정 종류: {turn.get(\'kind\')}")\n    if turn.get("kind") == "Selection":\n        # 멀티 선택 안내(사용자 결함 보고 2026-08-01): 반복 구조를 모르면 에이전트가 오판한다\n        picked = turn.get("selectedCount")\n        lines.append(f"※ 선택 창: 후보를 하나 고르면 같은 창이 다시 온다(여러 장 선택 구조)."\n                     f" 원하는 만큼 고른 뒤 \'선택 종료\'로 확정."\n                     + (f" 지금까지 {picked}장 선택됨." if isinstance(picked, int) else ""))\n    lines.append("가능한 행동:")\n    for action in turn.get("legalActions") or []:\n        desc = action["desc"]\n        if names:\n            # 서술 속 카드번호(ST1_15/BT1-029 양식 공존)에 한글명 병기\n            desc = _CARD_ID.sub(lambda m: _card(m.group(1).replace("_", "-"), names), desc)\n        lines.append(f"  {action[\'index\']}: {desc}")\n    return "\\n".join(lines)\n',
  'policies': '"""참가 정책 — RandomPolicy(검증·바닥선) / LLMPolicy(OpenAI 호환 endpoint).\n\nLLMPolicy는 chat completions 규격(base_url/api_key/model)만 전제 — OpenAI·로컬(vLLM,\nOllama의 /v1)·상용 호환 서버 전부 같은 코드로 붙는다. 응답에서 첫 정수를 착수 인덱스로\n파싱하고, 실패는 무작위 합법 수 폴백(판을 죽이지 않는다 — 착수 제한 시간이 있으므로).\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport random\nimport re\n\nimport aiohttp\n\nfrom dcgo_arena.state_text import state_to_text\n\n\nclass RandomPolicy:\n    def __init__(self, seed: int = 0):\n        self._rng = random.Random(seed)\n\n    def __call__(self, turn: dict) -> int:\n        return self._rng.choice([a["index"] for a in turn["legalActions"]])\n\n\nSYSTEM_PROMPT = """당신은 디지몬 카드 게임(DCGO) 플레이어입니다.\n매 턴 현재 보드 상태와 가능한 행동 목록을 받습니다.\n목표: 상대 시큐리티를 모두 깨고 마지막 공격을 성공시켜 승리하는 것.\n반드시 가능한 행동 목록에 있는 인덱스 하나만 고르고, 다음 JSON만 출력하세요:\n{"index": <番号>, "why": "<한 줄 근거>"}"""\n\n\nclass LLMPolicy:\n    def __init__(self, base_url: str, api_key: str, model: str,\n                 system_prompt: str = SYSTEM_PROMPT, temperature: float = 0.3,\n                 seed: int = 0, verbose: bool = False):\n        self.base_url = base_url.rstrip("/")\n        self.api_key = api_key\n        self.model = model\n        self.system_prompt = system_prompt\n        self.temperature = temperature\n        self._rng = random.Random(seed)\n        self.verbose = verbose\n\n    async def __call__(self, turn: dict) -> int:\n        legal = [a["index"] for a in turn["legalActions"]]\n        try:\n            async with aiohttp.ClientSession() as session:\n                async with session.post(\n                        f"{self.base_url}/chat/completions",\n                        headers={"Authorization": f"Bearer {self.api_key}",\n                                 "Content-Type": "application/json"},\n                        json={"model": self.model, "temperature": self.temperature,\n                              "messages": [{"role": "system", "content": self.system_prompt},\n                                           {"role": "user", "content": state_to_text(turn)}]},\n                        timeout=aiohttp.ClientTimeout(total=45)) as response:\n                    body = await response.json()\n            content = body["choices"][0]["message"]["content"]\n            if self.verbose:\n                print(f"[LLM] {content[:120]}")\n            index = self._parse_index(content)\n            if index in legal:\n                return index\n        except (aiohttp.ClientError, KeyError, json.JSONDecodeError, TimeoutError) as ex:\n            if self.verbose:\n                print(f"[LLM 오류 → 무작위 폴백] {ex}")\n        return self._rng.choice(legal)\n\n    @staticmethod\n    def _parse_index(content: str) -> int | None:\n        try:\n            return int(json.loads(content).get("index"))\n        except (json.JSONDecodeError, TypeError, ValueError):\n            pass\n        match = re.search(r\'"index"\\s*:\\s*(\\d+)\', content) or re.search(r"\\b(\\d+)\\b", content)\n        return int(match.group(1)) if match else None\n',
  'client': '"""ArenaClient — 아레나 ws 프로토콜(설계 §3.2)의 파이썬 클라이언트.\n\n서버→ hello | queued | room_created | match_start | your_turn | match_end | error\n클라→ enqueue | create_room | join_room | action | resign\n\n정책은 콜러블 하나: policy(turn: dict) -> int (착수 인덱스). turn에는 kind/state(관측 필터\n적용된 보드)/legalActions([{index, desc}])가 실린다. 불법 수는 서버가 retry로 되돌려주며\n클라이언트는 정책을 다시 호출한다(무한 방지 카운터 포함).\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom typing import Awaitable, Callable\n\nimport aiohttp\n\nPolicy = Callable[[dict], "int | Awaitable[int]"]\n\n\nclass ArenaError(RuntimeError):\n    pass\n\n\nclass ArenaClient:\n    def __init__(self, server: str, key: str):\n        self.server = server.rstrip("/")\n        self.key = key\n        self.handle: str | None = None\n\n    def _ws_url(self) -> str:\n        return self.server.replace("http://", "ws://").replace("https://", "wss://") + f"/arena?key={self.key}"\n\n    async def play(self, policy: Policy, mode: str = "ladder", room_code: str | None = None,\n                   on_event: Callable[[dict], None] | None = None) -> dict:\n        """한 판 참가(완주까지). mode = ladder | create_room | join_room. 결과 match_end를 반환."""\n        import inspect\n\n        async def decide(turn: dict) -> int:\n            picked = policy(turn)\n            return await picked if inspect.isawaitable(picked) else picked\n\n        async with aiohttp.ClientSession() as session:\n            async with session.ws_connect(self._ws_url(), heartbeat=30) as ws:\n                async for raw in ws:\n                    if raw.type != aiohttp.WSMsgType.TEXT:\n                        break\n                    msg = json.loads(raw.data)\n                    if on_event:\n                        on_event(msg)\n                    kind = msg.get("type")\n\n                    if kind == "hello":\n                        self.handle = msg.get("handle")\n                        if mode == "create_room":\n                            await ws.send_json({"type": "create_room"})\n                        elif mode == "join_room":\n                            if not room_code:\n                                raise ArenaError("join_room에는 room_code 필요")\n                            await ws.send_json({"type": "join_room", "code": room_code})\n                        elif mode == "practice":\n                            await ws.send_json({"type": "practice"})   # 연습판 — 레이팅·이력 미반영\n                        else:\n                            await ws.send_json({"type": "enqueue"})\n\n                    elif kind == "your_turn":\n                        retries = 0\n                        index = await decide(msg)\n                        await ws.send_json({"type": "action", "index": int(index)})\n                        # 불법 수 재시도는 서버 error(retry)로 돌아온다 — 아래 error 분기에서 처리하기\n                        # 위해 마지막 turn을 보관.\n                        self._last_turn, self._retries = msg, retries\n\n                    elif kind == "error":\n                        if msg.get("retry") and getattr(self, "_last_turn", None) is not None:\n                            self._retries = getattr(self, "_retries", 0) + 1\n                            if self._retries > 5:\n                                await ws.send_json({"type": "resign"})\n                                continue\n                            index = await decide(self._last_turn)\n                            await ws.send_json({"type": "action", "index": int(index)})\n                        elif msg.get("code") in ("auth", "no_deck", "no_room", "busy", "host_unavailable", "engine"):\n                            raise ArenaError(f"{msg.get(\'code\')}: {msg.get(\'message\')}")\n\n                    elif kind == "match_end":\n                        return msg\n\n        raise ArenaError("연결이 판 종료 전에 닫혔습니다")\n\n    # ---- 덱/이력 REST (키 인증 표면) ----\n\n    async def _api(self, method: str, path: str, body: dict | None = None) -> dict | list:\n        async with aiohttp.ClientSession() as session:\n            async with session.request(method, f"{self.server}{path}",\n                                       headers={"X-Arena-Key": self.key, "Content-Type": "application/json"},\n                                       data=json.dumps(body) if body is not None else None) as response:\n                return await response.json()\n\n    async def me(self) -> dict:\n        return await self._api("GET", "/api/arena/me")\n\n    async def cards(self) -> dict:\n        """카드 사전(이름·한글명·종류·풀) — 상태 서술 한글 병기용."""\n        return await self._api("GET", "/api/arena/cards")\n\n    async def decks(self) -> list:\n        """등록 덱 조회(읽기 전용) — 생성·수정·활성 지정은 웹 참가자 페이지 전용(2026-07-31 확정)."""\n        return await self._api("GET", "/api/arena/decks")\n\n    async def history(self) -> list:\n        return await self._api("GET", "/api/arena/history")\n',
  'config': '"""dcgo-arena.toml 설정 로더 — 온보딩 개선 ①(요구 §8.7).\n\n참가자는 파일 한 장으로 참가한다:\n\n    # dcgo-arena.toml\n    server = "http://서버:8791"\n    key = "발급받은 API 키"\n\n    [agent]                # 생략 시 무작위 합법 수\n    kind = "llm"           # random | llm | file\n    base_url = "http://localhost:11434/v1"\n    api_key = "none"\n    model = "llama3"\n    # kind="file"이면: path = "my_agent.py"  (act(state_text, actions)->index 정의)\n\n탐색 순서: --config 인자 > ./dcgo-arena.toml > ~/.config/dcgo-arena.toml\n"""\n\nfrom __future__ import annotations\n\nimport tomllib\nfrom pathlib import Path\n\nSEARCH = (Path("dcgo-arena.toml"), Path.home() / ".config" / "dcgo-arena.toml")\n\n\ndef load_config(path: str | None = None) -> dict:\n    candidates = [Path(path)] if path else list(SEARCH)\n    for candidate in candidates:\n        if candidate.is_file():\n            with open(candidate, "rb") as f:\n                data = tomllib.load(f)\n            data["_source"] = str(candidate)\n            return data\n    return {}\n\n\ndef build_agent(config: dict, seed: int = 0, verbose: bool = False):\n    """설정의 [agent] → 정책 콜러블. kind=file은 사용자 파이썬 파일의 act()를 싣는다."""\n    from dcgo_arena.policies import LLMPolicy, RandomPolicy\n\n    agent = config.get("agent") or {}\n    kind = agent.get("kind", "random")\n\n    if kind == "llm":\n        base = agent.get("base_url", "")\n        model = agent.get("model", "")\n        if not base or not model:\n            raise SystemExit("[agent] kind=llm에는 base_url과 model이 필요합니다")\n        return LLMPolicy(base, agent.get("api_key", "none"), model,\n                         temperature=float(agent.get("temperature", 0.3)),\n                         seed=seed, verbose=verbose,\n                         **({"system_prompt": agent["system_prompt"]} if agent.get("system_prompt") else {}))\n\n    if kind == "file":\n        return load_agent_file(agent.get("path", ""), seed)\n\n    return RandomPolicy(seed)\n\n\ndef load_agent_file(path: str, seed: int = 0):\n    """커스텀 에이전트 파일: `def act(state_text, actions) -> index` 하나만 요구(온보딩 ② 규격).\n    actions = [{"index", "desc"}]. 원하면 act(state_text, actions, turn)로 원본 turn까지 받을 수 있다."""\n    import importlib.util\n    import inspect\n\n    from dcgo_arena.state_text import state_to_text\n\n    file = Path(path)\n    if not file.is_file():\n        raise SystemExit(f"에이전트 파일 없음: {path}")\n    spec = importlib.util.spec_from_file_location("dcgo_arena_user_agent", file)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    act = getattr(module, "act", None)\n    if not callable(act):\n        raise SystemExit(f"{path}에 act(state_text, actions) 함수가 없습니다")\n    wants_turn = len(inspect.signature(act).parameters) >= 3\n\n    async def policy(turn: dict) -> int:\n        args = [state_to_text(turn), turn.get("legalActions") or []]\n        if wants_turn:\n            args.append(turn)\n        result = act(*args)\n        if inspect.isawaitable(result):\n            result = await result\n        return int(result)\n\n    return policy\n',
  'agents': '"""에이전트 네임스페이스 — TextArena의 ta.agents.* 관례를 따르는 표면.\n\n모든 에이전트는 콜러블: agent(turn: dict) -> int (착수 인덱스). 문자열 관측이 필요한\n커스텀 구현은 from_file(act(state_text, actions)->index) 규격을 쓰면 된다.\n"""\n\nfrom __future__ import annotations\n\nfrom dcgo_arena.config import load_agent_file\nfrom dcgo_arena.policies import LLMPolicy, RandomPolicy\n\n\ndef Random(seed: int = 0):\n    """무작위 합법 수 — 연결 검증·바닥선."""\n    return RandomPolicy(seed)\n\n\ndef OpenAICompat(base_url: str, model: str, api_key: str = "none",\n                 system_prompt: str | None = None, temperature: float = 0.3,\n                 seed: int = 0, verbose: bool = False):\n    """OpenAI 호환 chat completions endpoint — OpenAI·OpenRouter·vLLM·Ollama(/v1) 공용."""\n    kwargs = {"temperature": temperature, "seed": seed, "verbose": verbose}\n    if system_prompt:\n        kwargs["system_prompt"] = system_prompt\n    return LLMPolicy(base_url, api_key, model, **kwargs)\n\n\ndef from_file(path: str, seed: int = 0):\n    """사용자 파일의 act(state_text, actions)->index 를 에이전트로."""\n    return load_agent_file(path, seed)\n\n\ndef ClaudeCode(command: str = "claude", model: str | None = None,\n               strategy: str = "", seed: int = 0, verbose: bool = False):\n    """Claude Code CLI(공식 도구·구독 과금) 헤드리스 브리지 — 착수마다 `claude -p`로 수를 고른다.\n\n    구독(Pro/Max) 사용자용 정식 경로(2026-08-01): 서드파티 OAuth가 금지·차단된 뒤에도\n    Claude Code 자체는 자사 제품이라 구독 사용이 허용된다. 전제 = `claude` CLI 설치·로그인.\n    파싱 실패·타임아웃(50초)은 무작위 합법 수 폴백 — 착수 제한(기본 60초) 안에서 판을 지킨다."""\n    import asyncio\n    import json as _json\n    import random as _random\n    import re as _re\n\n    from dcgo_arena.state_text import state_to_text\n\n    rng = _random.Random(seed)\n\n    async def agent(turn: dict) -> int:\n        legal = [a["index"] for a in turn["legalActions"]]\n        prompt = (\n            "디지몬 카드 게임(DCGO) 한 수를 고른다. 아래 보드 상태와 합법 행동 목록을 보고 "\n            "가장 유리한 행동 인덱스 하나를 고르라.\\n"\n            + (f"\\n[전략 지침]\\n{strategy}\\n" if strategy.strip() else "")\n            + "\\n" + state_to_text(turn)\n            + "\\n\\n반드시 다음 JSON 한 줄만 출력: {\\"index\\": <합법 인덱스>}"\n        )\n        args = [command, "-p", prompt]\n        if model:\n            args += ["--model", model]\n        try:\n            proc = await asyncio.create_subprocess_exec(\n                *args, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL)\n            out, _ = await asyncio.wait_for(proc.communicate(), timeout=50)\n            text = out.decode("utf-8", errors="replace")\n            if verbose:\n                print(f"[claude] {text[:120]}")\n            found = _re.search(r\'\\{[^{}]*"index"\\s*:\\s*(\\d+)[^{}]*\\}\', text)\n            index = int(found.group(1)) if found else int(_json.loads(text)["index"])\n            if index in legal:\n                return index\n        except Exception:\n            pass\n        return rng.choice(legal)   # 폴백 — 몰수패 방지가 우선\n\n    return agent\n',
  'highlevel': '"""da.play / da.daemon — TextArena식 한 호출 참가.\n\n    import dcgo_arena as da\n    da.play(server=..., key=...,\n            agent=da.agents.OpenAICompat(...),   # 생략 = 무작위\n            games=10)                            # daemon=True 로 상주\n\n덱은 SDK가 관여하지 않는다(사용자 확정 2026-07-31): 생성·수정·사용 덱 지정 전부\n웹 참가자 페이지 전용이며, 서버는 항상 그 계정의 활성 덱으로 참가시킨다.\n활성 덱이 없으면 no_deck 에러 — 웹에서 덱을 등록·지정한 뒤 다시 실행한다.\n"""\n\nfrom __future__ import annotations\n\nimport asyncio\nimport random\n\nfrom dcgo_arena.client import ArenaClient, ArenaError\nfrom dcgo_arena.policies import RandomPolicy\n\n\ndef _default_on_event(msg: dict) -> None:\n    kind = msg.get("type")\n    if kind == "hello":\n        print(f"[{msg[\'handle\']}] 접속 — 시즌 {msg[\'season\']}")\n    elif kind == "room_created":\n        print(f"방 코드: {msg[\'code\']} (상대에게 전달)", flush=True)\n    elif kind == "queued":\n        print("큐 대기" + (f" {msg[\'position\']}번째" if msg.get("position") else "")\n              + (f" — {msg[\'notice\']}" if msg.get("notice") else ""))\n    elif kind == "match_start":\n        print(f"매치 {msg[\'matchId\']} — 좌석 {msg[\'seat\']}, 상대 {msg[\'opponent\'][\'handle\']}"\n              f"({msg[\'opponent\'][\'rating\']}){\' [검증판]\' if msg.get(\'verification\') else \'\'}")\n\n\nasync def _run(server: str, key: str, agent, games: int,\n               daemon: bool, room: str | None, join: str | None, on_event) -> list[dict]:\n    client = ArenaClient(server, key)\n    me = await client.me()\n    if me.get("error"):\n        raise ArenaError("API 키가 유효하지 않습니다 — 참가자 페이지에서 확인하세요")\n    agent = agent or RandomPolicy(random.randrange(1, 2 ** 30))\n    on_event = on_event or _default_on_event\n    results = []\n    mode = "create_room" if room == "create" else "join_room" if join else "ladder"\n\n    if daemon:\n        backoff = 3\n        while True:\n            try:\n                result = await client.play(agent, mode="ladder", on_event=on_event)\n                print(f"종료: winner={result.get(\'winnerSeat\')} reason={result.get(\'reason\')}"\n                      f" Δ={result.get(\'ratingDelta\')}", flush=True)\n                results.append(result)\n                backoff = 3\n            except (ArenaError, OSError) as ex:\n                print(f"연결 문제({ex}) — {backoff}초 후 재접속", flush=True)\n                await asyncio.sleep(backoff)\n                backoff = min(backoff * 2, 60)\n\n    for _ in range(max(1, games)):\n        result = await client.play(agent, mode=mode, room_code=join, on_event=on_event)\n        print(f"종료: winner={result.get(\'winnerSeat\')} reason={result.get(\'reason\')}"\n              f" Δ={result.get(\'ratingDelta\')}")\n        results.append(result)\n        if mode != "ladder":\n            break\n    return results\n\n\ndef play(server: str, key: str, agent=None, games: int = 1,\n         daemon: bool = False, room: str | None = None, join: str | None = None,\n         on_event=None) -> list[dict]:\n    """참가 한 호출. games=N 래더 연전, daemon=True 상주, room="create"/join="코드" 룸 매치.\n    덱은 웹 참가자 페이지에서 지정한 활성 덱이 자동 적용된다."""\n    return asyncio.run(_run(server, key, agent, games, daemon, room, join, on_event))\n\n\ndef daemon(server: str, key: str, agent=None, on_event=None) -> None:\n    """상주 참가 — play(daemon=True)의 별칭."""\n    play(server, key, agent=agent, daemon=True, on_event=on_event)\n',
  'seatbridge': '"""seat 파일 브리지 — 에이전트 앱(Claude Code/Codex 등)의 세션 AI가 직접 수를 두는 통로.\n\n사용자 확정(2026-08-01): 참가 UX = 에이전트 앱에서 스킬(/디지몬한판)을 호출하면 그 세션의\nAI가 한 판을 직접 진행한다. ws는 착수 제한(기본 60초)이 있어 연결을 물고 있을 상주가 필요\n한데, 세션 AI는 소켓을 직접 못 잡으므로 이 브리지가 파일로 중계한다:\n\n    브리지(백그라운드): ws 접속·매칭 → 결정마다 <dir>/turn.json 기록 → <dir>/answer.json 대기\n    에이전트(세션 AI):  turn.json의 stateText·legalActions를 읽고 {"index": N}을 answer.json에\n\n  - {"auto": "random"} 을 쓰면 남은 판을 무작위 합법 수로 자동 완주(긴 판 이관·이탈용)\n  - 55초 무응답·불법 인덱스 반복 시 무작위 폴백 — 몰수패 방지가 우선\n  - 판이 끝나면 <dir>/result.json 기록 후 종료\n"""\n\nfrom __future__ import annotations\n\nimport asyncio\nimport json\nimport random\nimport time\nfrom pathlib import Path\n\nfrom dcgo_arena.client import ArenaClient\nfrom dcgo_arena.state_text import state_to_text\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    tmp = path.with_suffix(path.suffix + ".tmp")\n    tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=1), encoding="utf-8")\n    tmp.replace(path)   # 원자 교체 — 에이전트가 반쯤 쓰인 파일을 읽지 않게\n\n\nasync def run_seat(server: str, key: str, directory: str = ".dcgo-seat",\n                   mode: str = "ladder", join: str | None = None, seed: int = 0,\n                   lang: str | None = None) -> dict:\n    d = Path(directory)\n    d.mkdir(parents=True, exist_ok=True)\n    for name in ("turn.json", "answer.json", "result.json", "status.json"):\n        (d / name).unlink(missing_ok=True)\n\n    rng = random.Random(seed or random.randrange(1, 2 ** 30))\n    auto = {"on": False}\n    counter = {"n": 0}\n    names: dict = {}   # 카드번호→한글명 — 접속 후 채움(실패 시 빈 채로 영문 진행)\n\n    async def policy(turn: dict) -> int:\n        legal = [a["index"] for a in turn["legalActions"]]\n        if auto["on"]:\n            return rng.choice(legal)\n        counter["n"] += 1\n        (d / "answer.json").unlink(missing_ok=True)\n        payload = {"turnNo": counter["n"], "kind": turn.get("kind"),\n                   "stateText": state_to_text(turn, names),\n                   "legalActions": turn.get("legalActions")}\n        _write_json(d / "turn.json", payload)\n\n        deadline = time.monotonic() + 55   # 서버 착수 제한(60초) 안쪽\n        while time.monotonic() < deadline:\n            if (d / "answer.json").exists():\n                try:\n                    answer = json.loads((d / "answer.json").read_text(encoding="utf-8"))\n                except (OSError, json.JSONDecodeError):\n                    await asyncio.sleep(0.2)\n                    continue\n                (d / "answer.json").unlink(missing_ok=True)\n                if answer.get("auto") == "random":\n                    auto["on"] = True\n                    return rng.choice(legal)\n                index = int(answer.get("index", -1))\n                if index in legal:\n                    return index\n                payload["error"] = f"불법 인덱스 {index} — legalActions에서 다시 고르세요"\n                _write_json(d / "turn.json", payload)\n            await asyncio.sleep(0.3)\n        return rng.choice(legal)   # 무응답 폴백\n\n    def on_event(msg: dict) -> None:\n        if msg.get("type") == "match_start" and mode == "practice" and not msg.get("practice"):\n            # 연습 요청이 랭킹전으로 성립 = 클라이언트/서버 버전 불일치(실측 2026-08-01:\n            # 과도기 SDK의 --practice 무시 폴백) — 조용히 랭킹전을 두는 것보다 즉시 중단이 낫다.\n            raise RuntimeError("연습판(--practice) 요청이 랭킹전으로 성립 — SDK를 서버에서 새로 받으세요")\n        if msg.get("type") in ("hello", "queued", "match_start", "room_created"):\n            _write_json(d / "status.json", msg)\n            print(json.dumps(msg, ensure_ascii=False), flush=True)\n\n    client = ArenaClient(server, key)\n    # 카드명 언어(사용자 확정 2026-08-01): --lang > 서버 계정 설정(me.lang) > ko.\n    # ko = 한글명(없으면 영문 폴백), en = 영문명. 실패해도 판은 카드번호로 진행.\n    try:\n        if lang is None:\n            lang = str((await client.me()).get("lang") or "ko")\n        card_data = await client.cards()\n        for cid, c in (card_data.get("cards") or {}).items():\n            name = c.get("name") if lang == "en" else (c.get("nameKo") or c.get("name"))\n            if name:\n                names[cid] = name\n    except Exception:\n        pass\n    result = await client.play(policy, mode=mode, room_code=join, on_event=on_event)\n    (d / "turn.json").unlink(missing_ok=True)\n    _write_json(d / "result.json", result)\n    print("결과: " + json.dumps(result, ensure_ascii=False), flush=True)\n    return result\n',
  '__main__': '"""dcgo-arena CLI — `python -m dcgo_arena play|daemon [--config 파일]` (온보딩 ①·④).\n\nplay   : 한 판(래더) 참가 후 종료. --create-room/--join 도 지원.\ndaemon : 상주 — 접속 유지, 서버 자동 매칭/래더로 판이 잡히는 대로 계속 둔다. 끊기면 재접속.\n설정은 dcgo-arena.toml(config.py 참조). CLI 인자가 설정보다 우선.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport asyncio\nimport random\n\nfrom dcgo_arena.client import ArenaClient, ArenaError\nfrom dcgo_arena.config import build_agent, load_config\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(prog="dcgo-arena")\n    parser.add_argument("mode", choices=["play", "daemon", "seat"], nargs="?", default="play")\n    parser.add_argument("--dir", default=".dcgo-seat", help="seat 모드 파일 브리지 디렉터리")\n    parser.add_argument("--config", default=None, help="dcgo-arena.toml 경로")\n    parser.add_argument("--server", default=None)\n    parser.add_argument("--key", default=None)\n    parser.add_argument("--create-room", action="store_true")\n    parser.add_argument("--join", default=None)\n    parser.add_argument("--practice", action="store_true", help="연습판(하우스 봇, 레이팅·이력 미반영)")\n    parser.add_argument("--lang", choices=["ko", "en"], default=None,\n                        help="카드명 언어(생략 시 서버 계정 설정)")\n    parser.add_argument("--games", type=int, default=1, help="play 모드 래더 연전 판수")\n    parser.add_argument("--seed", type=int, default=None)\n    parser.add_argument("--quiet", action="store_true")\n    return parser.parse_args()\n\n\nasync def run() -> None:\n    args = parse_args()\n    config = load_config(args.config)\n    server = args.server or config.get("server")\n    key = args.key or config.get("key")\n    if not server or not key:\n        raise SystemExit("server/key가 필요합니다 — dcgo-arena.toml 또는 --server/--key "\n                         "(참가자 페이지의 퀵스타트에서 설정 파일을 복사하세요)")\n    seed = args.seed if args.seed is not None else random.randrange(1, 2 ** 30)\n    agent = build_agent(config, seed=seed, verbose=not args.quiet)\n    client = ArenaClient(server, key)\n    if config.get("_source") and not args.quiet:\n        print(f"설정: {config[\'_source\']}")\n\n    def on_event(msg: dict) -> None:\n        kind = msg.get("type")\n        if args.quiet:\n            if kind == "room_created":\n                print(f"방 코드: {msg[\'code\']}", flush=True)\n            return\n        if kind == "hello":\n            print(f"[{msg[\'handle\']}] 접속 — 시즌 {msg[\'season\']}")\n        elif kind == "room_created":\n            print(f"방 생성됨 — 코드: {msg[\'code\']} (상대에게 전달)", flush=True)\n        elif kind == "queued":\n            print(f"래더 큐 {msg[\'position\']}번째")\n        elif kind == "match_start":\n            print(f"매치 {msg[\'matchId\']} — 좌석 {msg[\'seat\']}, 상대 {msg[\'opponent\'][\'handle\']}"\n                  f"({msg[\'opponent\'][\'rating\']}){\' [검증판]\' if msg.get(\'verification\') else \'\'}")\n        elif kind == "your_turn":\n            print(f"  s{msg[\'stepIndex\']} {msg.get(\'kind\')} — 합법 {len(msg.get(\'legalActions\') or [])}수")\n\n    if args.mode == "seat":\n        # 파일 브리지(스킬 경로): 세션 AI가 turn.json/answer.json으로 직접 착수.\n        # --practice = 상대가 하우스 봇(자동)인 연습판 — botPlay(2026-08-01 재정의)\n        from dcgo_arena.seatbridge import run_seat\n        seat_mode = ("create_room" if args.create_room else "join_room" if args.join\n                     else "practice" if args.practice else "ladder")\n        await run_seat(server, key, args.dir, mode=seat_mode, join=args.join, seed=seed,\n                       lang=args.lang)\n        return\n\n    if args.mode == "daemon":\n        backoff = 3\n        while True:\n            try:\n                result = await client.play(agent, mode="ladder", on_event=on_event)\n                print(f"종료: winner={result.get(\'winnerSeat\')} reason={result.get(\'reason\')}"\n                      f" Δ={result.get(\'ratingDelta\')}", flush=True)\n                backoff = 3\n            except (ArenaError, OSError) as ex:\n                print(f"연결 문제({ex}) — {backoff}초 후 재접속", flush=True)\n                await asyncio.sleep(backoff)\n                backoff = min(backoff * 2, 60)\n        return\n\n    mode = ("create_room" if args.create_room else "join_room" if args.join\n            else "practice" if args.practice else "ladder")\n    for _ in range(args.games):\n        result = await client.play(agent, mode=mode, room_code=args.join,\n                                   on_event=on_event)\n        print(f"종료: winner={result.get(\'winnerSeat\')} reason={result.get(\'reason\')}"\n              f" Δ={result.get(\'ratingDelta\')}"\n              + (" [연습 — 미반영]" if result.get("practice") else ""))\n        if mode not in ("ladder", "practice"):\n            break\n\n\ndef main() -> None:\n    asyncio.run(run())\n\n\nif __name__ == "__main__":\n    main()\n',
}
for _name in ['state_text', 'policies', 'client', 'config', 'agents', 'highlevel', 'seatbridge', '__main__']:
    _mod = types.ModuleType(f'dcgo_arena.{_name}')
    _mod.__package__ = 'dcgo_arena'
    sys.modules[f'dcgo_arena.{_name}'] = _mod
    exec(compile(_SOURCES[_name], f'dcgo_arena/{_name}.py', 'exec'), _mod.__dict__)
exec(compile(_SOURCES['__init__'], 'dcgo_arena/__init__.py', 'exec'), _pkg.__dict__)
if __name__ == '__main__':
    sys.modules['dcgo_arena.__main__'].main()
